const audio = { music:(function(){try{var t=window.top;if(t.PortalMusic)return t.PortalMusic.proxy;}catch(e){}return null;})()||new Audio('/assets/audio/musica-portal.mp3'), tap:PMS('/juegos/aura-game/assets/audio/toque-luminoso.mp3'), reveal:PMS('/juegos/aura-game/assets/audio/revelacion-astral.mp3') };
